UPDATE public.inscription_media SET description='Bjärby. Runsignum Öl 36, Öl 32 — Anmärkning (övrig): Alternativa runsignum: B 1055, B 1079, BN 68, L 1306
Beskrivning: Bild 1: Öl 36. Upphov: Hans Adam Reinhold Sidén (1874). Bildtext: "Runsten stående invid östra sidan om landsvägen vid Bjärby by, stenen är något skadad hvarför skriften på åtskilliga ställen är alldeles borta och otydlig, Runstens sn. Afteckn. 1874 af H.A.R. Sidén. 1 dec tum = 20 Fot." || Bild 2: Öl 36. Upphov: Hans Adam Reinhold Sidén (1872). Bildtext: "Runsten, stående på östra sidan om och straxt invid landsvägen mitt för Bjerby by, i Runstens socken på Öland. &amp; ett uttaget stycke ur stenen - b.b. runskriften skadad och otydlig, aftecknad den 26 April 1872 af H.A.R. Sidén. 1 dec: tum = 2 fot." || Bild 3: Öl 36, Öl 32. Upphov: Okänd (Okänt år). Bildtext: Osignerade teckningar. [Foto] (Källa: http://kulturarvsdata.se/raa/dokumentation/981b6125-d2ac-409f-a5af-6b5a5c12ef19)', photographer='Hans Adam Reinhold Sidén', copyright_info='https://creativecommons.org/publicdomain/mark/1.0/', media_type='photo' WHERE media_url='https://pub.raa.se/dokumentation/981b6125-d2ac-409f-a5af-6b5a5c12ef19/visning/1';
