UPDATE public.inscription_media SET description='Karlevi. Runsignum Öl 1 — Anmärkning (övrig): Alternativa runsignum: B 1071, BN 1, DR 411, L 1323
Beskrivning: Bild 1: Öl 1. Upphov: Hans Adam Reinhold Sidén (1874). Bildtext: "Carlevi Runsten, belägen vest nord vest om Carlevi by i närheten af sjön, ehuru stenen är granit har den till en del så förvittrad att skriften på en del ställen är otydlig. Som stenen är nästan rund har jag för skriftens läsning måst tecknat den på detta sättet. Afteckn. af H.A.R. Sidén 1874. 1 dec tum = 1 fot." || Bild 2: Öl 1. Upphov: Okänd (Okänt år). || Bild 3: Öl 1. Upphov: Jonas Rhezelius (1634). Bildtext: Rhezelius, Monum. Runica 1634. 04007615. [Foto] (Källa: http://kulturarvsdata.se/raa/dokumentation/ba98560c-d7fc-43ad-b089-9fbabb03722d)', photographer='Hans Adam Reinhold Sidén', copyright_info='https://creativecommons.org/publicdomain/mark/1.0/', media_type='photo' WHERE media_url='https://pub.raa.se/dokumentation/ba98560c-d7fc-43ad-b089-9fbabb03722d/visning/1';
